// Written with the help of Claude
// AI Usage Note: generated by Claude; every case checked against PoliteHttpClient by running the tests.
import assert from 'node:assert/strict';
import { createServer, type Server } from 'node:http';
import type { AddressInfo } from 'node:net';
import { after, before, describe, mock, test } from 'node:test';
import { Logger } from '@nestjs/common';
import { PoliteHttpClient, redactedUrl } from '../../dist/infra/providers/http-client.js';

// REL-003: a provider page that fails now and then is retried, not lost.
describe('PoliteHttpClient', () => {
  let server: Server;
  let baseUrl: string;
  const received: { path: string | undefined; userAgent: string | undefined; at: number }[] = [];
  let failuresLeft = 0;

  before(async () => {
    server = createServer((req, res) => {
      received.push({ path: req.url, userAgent: req.headers['user-agent'], at: Date.now() });
      if (req.url?.startsWith('/down')) {
        res.writeHead(503).end();
        return;
      }
      if (req.url?.startsWith('/flaky') && failuresLeft > 0) {
        failuresLeft--;
        res.writeHead(503).end();
        return;
      }
      res.writeHead(req.url === '/missing' ? 404 : 200).end(`page ${req.url}`);
    });
    await new Promise<void>((resolve) => server.listen(0, resolve));
    baseUrl = `http://localhost:${(server.address() as AddressInfo).port}`;
    mock.method(Logger.prototype, 'warn', () => {});
  });

  after(async () => {
    mock.restoreAll();
    await new Promise<void>((resolve) => server.close(() => resolve()));
  });

  const client = (options: Partial<ConstructorParameters<typeof PoliteHttpClient>[0]> = {}) =>
    new PoliteHttpClient({ userAgent: 'NearbyImport/test', intervalMs: 0, backoffMs: 1, ...options });

  test('sends the User-Agent and returns the page', async () => {
    received.length = 0;

    const response = await client().get(`${baseUrl}/concerts/`);

    assert.deepEqual([response.status, response.text], [200, 'page /concerts/']);
    assert.equal(received[0]?.userAgent, 'NearbyImport/test');
  });

  test('waits the interval between two requests', async () => {
    received.length = 0;
    const polite = client({ intervalMs: 150 });

    await Promise.all([polite.get(`${baseUrl}/a`), polite.get(`${baseUrl}/b`)]);

    // Measured where the server receives them, so the first connection's setup can eat into the gap a little.
    const [first, second] = received;
    assert.ok(first && second && second.at - first.at >= 100, `${second?.at} - ${first?.at}`);
  });

  test('never sends before the interval has passed, even when the timer fires a millisecond early', async () => {
    let now = 1_000_000;
    const sleeps: number[] = [];
    // The first wait ends a millisecond early, as a real timer may; the next ones on time.
    const early = {
      now: () => now,
      sleep: (ms: number) => {
        now += sleeps.length === 0 ? ms - 1 : ms;
        sleeps.push(ms);
        return Promise.resolve();
      },
    };
    const sentAt: number[] = [];
    const realFetch = globalThis.fetch;
    const fetchMock = mock.method(globalThis, 'fetch', (...args: Parameters<typeof fetch>) => {
      sentAt.push(now);
      return realFetch(...args);
    });
    const polite = client({ intervalMs: 1000, clock: early });

    await polite.get(`${baseUrl}/a`);
    await polite.get(`${baseUrl}/b`);

    fetchMock.mock.restore();
    assert.equal(sentAt.length, 2);
    assert.ok((sentAt[1] ?? 0) - (sentAt[0] ?? 0) >= 1000, `${sentAt[1]} - ${sentAt[0]}`);
    assert.deepEqual(sleeps, [1000, 1]);
  });

  test('retries a 5xx answer and returns the page once it comes', async () => {
    received.length = 0;
    failuresLeft = 2;

    const response = await client().get(`${baseUrl}/flaky`);

    assert.equal(response.status, 200);
    assert.equal(received.length, 3);
  });

  test('returns a 404 at once, without retrying', async () => {
    received.length = 0;

    const response = await client().get(`${baseUrl}/missing`);

    assert.equal(response.status, 404);
    assert.equal(received.length, 1);
  });

  test('throws after the retries when the server cannot be reached, and logs it', async () => {
    const error = mock.method(Logger.prototype, 'error', () => {});

    await assert.rejects(client({ retries: 1 }).get('http://localhost:1/unreachable'));

    assert.equal(error.mock.callCount(), 1);
    assert.match(String(error.mock.calls[0]?.arguments[0]), /unreachable failed after 2 attempts .*; giving up/);
  });

  test('stops after the last retry of a server that keeps failing, and logs the last answer', async () => {
    received.length = 0;
    const error = mock.method(Logger.prototype, 'error', () => {});

    const response = await client({ retries: 2 }).get(`${baseUrl}/down`);

    assert.equal(response.status, 503);
    assert.equal(received.length, 3);
    assert.equal(error.mock.callCount(), 1);
    assert.match(String(error.mock.calls[0]?.arguments[0]), /\/down failed after 3 attempts \(status 503\); giving up/);
  });

  test('waits a random part of the doubled backoff, never more than maxBackoffMs', async () => {
    const random = mock.method(Math, 'random', () => 0.5);
    mock.method(Logger.prototype, 'error', () => {});
    const warn = mock.method(Logger.prototype, 'warn', () => {});

    await client({ retries: 3, backoffMs: 4, maxBackoffMs: 10 }).get(`${baseUrl}/down`);

    random.mock.restore();
    const waits = warn.mock.calls.map((call) => /retrying in (\d+) ms/.exec(String(call.arguments[0]))?.[1]);
    // Half of 4, 8 and 16 ms, the last capped at 10 ms.
    assert.deepEqual(waits, ['2', '4', '5']);
  });

  const disallowed = [{ site: 'Karabas', paths: ['/ajax.php'], url: '/ajax.php?action=events' }];
  for (const { site, paths, url } of disallowed) {
    test(`refuses ${url}, disallowed by the robots.txt of ${site}, without sending it`, async () => {
      received.length = 0;

      await assert.rejects(client({ disallowedPaths: paths }).get(`${baseUrl}${url}`), /disallowed by robots\.txt/);

      assert.equal(received.length, 0);
    });
  }

  test('logs a retried URL with its API key redacted', async () => {
    failuresLeft = 1;
    const warn = mock.method(Logger.prototype, 'warn', () => {});

    await client().get(`${baseUrl}/flaky?city=kyiv&apiKey=test-api-key&page=1`);

    const logged = warn.mock.calls.map((call) => String(call.arguments[0]));
    assert.equal(logged.length, 1);
    assert.match(logged[0] ?? '', /\?city=kyiv&apiKey=REDACTED&page=1 failed/);
    assert.ok(logged.every((line) => !line.includes('test-api-key')));
  });
});

describe('redactedUrl', () => {
  const urls = [
    {
      url: 'https://api.example/events?apiKey=abc&page=2',
      result: 'https://api.example/events?apiKey=REDACTED&page=2',
    },
    {
      url: 'https://api.example/events?page=2&apikey=abc',
      result: 'https://api.example/events?page=2&apikey=REDACTED',
    },
    { url: 'https://api.example/events?page=2', result: 'https://api.example/events?page=2' },
  ];
  for (const { url, result } of urls) {
    test(`writes ${url} as ${result}`, () => {
      assert.equal(redactedUrl(url), result);
    });
  }
});
